const body = $json.body || {};
const query = $json.query || {};
const isWebhook = Boolean($json.body || $json.query || $json.headers);
const source = isWebhook ? 'manual' : 'schedule';
const rawLimit = body.limit ?? query.limit ?? '';
const parsedLimit = Number.parseInt(rawLimit, 10);
const requestedLimit = Number.isInteger(parsedLimit) && parsedLimit > 0 ? Math.min(parsedLimit, 100) : null;
const queueId = String(body.queue_id || query.queue_id || '').trim();
const requestedDryRun = isWebhook
  ? !(body.dry_run === false || body.dry_run === 'false' || body.execute === true || body.execute === 'true')
  : false;
const realPostRequested = !requestedDryRun;

let limit;
let realPostLimitGuard = 'ok';
if (!realPostRequested) {
  limit = requestedLimit || 25;
} else if (source === 'schedule') {
  limit = 5;
  realPostLimitGuard = 'schedule_batch_5';
} else {
  limit = 1;
  realPostLimitGuard = requestedLimit && requestedLimit !== 1 ? 'manual_forced_to_1' : 'manual_limit_1';
}

const workerId = `cris08-${source}-${Date.now()}-${Math.random().toString(16).slice(2)}`;

return [{ json: {
  source,
  dry_run: requestedDryRun,
  requested_dry_run: requestedDryRun,
  real_post_requested: realPostRequested,
  requested_limit: requestedLimit,
  limit,
  real_post_limit_guard: realPostLimitGuard,
  worker_id: workerId,
  claim_ttl_minutes: 10,
  max_attempts: 3,
  queue_id: /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(queueId) ? queueId : ''
} }];

