={{ (() => {
  const prefix = `SET search_path TO sales_prod, public, extensions;
`;
  const limit = Math.max(1, Math.min(Number($json.limit || 1), 100));
  const workerId = String($json.worker_id || 'cris08-worker').replace(/'/g, "''").slice(0, 120);
  const queueId = String($json.queue_id || '').trim();
  const queueFilter = queueId
    ? `AND r.id = '${queueId.replace(/'/g, "''")}'::uuid`
    : '';
  const queueArg = queueId
    ? `'${queueId.replace(/'/g, "''")}'::uuid`
    : 'NULL::uuid';
  const claimTtl = Math.max(1, Math.min(Number($json.claim_ttl_minutes || 10), 60));
  const maxAttempts = Math.max(1, Math.min(Number($json.max_attempts || 3), 10));
  const source = String($json.source || 'manual').replace(/'/g, "''");
  const guard = String($json.real_post_limit_guard || '').replace(/'/g, "''");

  if ($json.real_post_requested === true || String($json.real_post_requested) === 'true') {
    return `${prefix}WITH selected AS (
  SELECT *
  FROM claim_quicklink_reports(${limit}, '${workerId}', interval '${claimTtl} minutes', ${maxAttempts}, ${queueArg})
)
SELECT
  false::boolean AS dry_run,
  true::boolean AS real_post_requested,
  '${source}'::text AS source,
  ${limit}::integer AS batch_limit,
  '${workerId}'::text AS worker_id,
  '${guard}'::text AS real_post_limit_guard,
  COUNT(s.id)::integer AS report_count,
  COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.created_at ASC, s.id ASC) FILTER (WHERE s.id IS NOT NULL), '[]'::jsonb) AS reports
FROM selected s;`;
  }

  return `${prefix}WITH selected AS (
  SELECT r.*
  FROM v_quicklink_report_pending r
  WHERE true ${queueFilter}
  ORDER BY r.created_at ASC, r.id ASC
  LIMIT ${limit}
)
SELECT
  true::boolean AS dry_run,
  false::boolean AS real_post_requested,
  '${source}'::text AS source,
  ${limit}::integer AS batch_limit,
  '${workerId}'::text AS worker_id,
  '${guard}'::text AS real_post_limit_guard,
  COUNT(s.id)::integer AS report_count,
  COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.created_at ASC, s.id ASC) FILTER (WHERE s.id IS NOT NULL), '[]'::jsonb) AS reports
FROM selected s;`;
})() }}

