const row = $input.first()?.json || {};
const reports = Array.isArray(row.reports) ? row.reports : [];
const realPostRequested = row.real_post_requested === true || String(row.real_post_requested) === 'true';

if (!realPostRequested) {
  const results = reports.map(report => ({
    queue_id: report.id,
    conversation_id: report.conversation_id,
    lead_id: report.lead_id,
    quicklink_id: report.quicklink_id,
    marca: report.marca,
    endpoint: report.endpoint,
    payload: report.payload,
    status: 'dry_run_ready'
  }));

  return [{ json: {
    route: 'response',
    status: 'dry_run_ok',
    dry_run: true,
    real_post_requested: false,
    source: row.source || 'manual',
    worker_id: row.worker_id,
    report_count: reports.length,
    would_post_count: reports.length,
    sent_count: 0,
    failed_count: 0,
    reports: results
  } }];
}

if (reports.length === 0) {
  return [{ json: {
    route: 'response',
    status: 'no_pending_reports',
    dry_run: false,
    real_post_requested: true,
    source: row.source || 'schedule',
    worker_id: row.worker_id,
    report_count: 0,
    sent_count: 0,
    failed_count: 0,
    reports: []
  } }];
}

return reports.map(report => ({ json: {
  route: 'real_post',
  dry_run: false,
  real_post_requested: true,
  source: row.source || 'schedule',
  worker_id: row.worker_id,
  real_post_limit_guard: row.real_post_limit_guard,
  queue_id: report.id,
  conversation_id: report.conversation_id,
  lead_id: report.lead_id,
  quicklink_id: report.quicklink_id,
  marca: report.marca,
  endpoint: report.endpoint,
  payload: report.payload,
  status: 'claimed_ready_to_post',
  processing_worker_id: report.processing_worker_id,
  processing_expires_at: report.processing_expires_at,
} }));

const httpItems = $input.all();
let reports = [];
try {
  reports = $('Code - Route Report Worker').all().map(item => item.json || {});
} catch (e) {
  reports = [];
}

function esc(value) {
  return String(value == null ? '' : value).replace(/'/g, "''");
}

function parseBody(body) {
  if (typeof body !== 'string') return body;
  try { return JSON.parse(body); } catch (e) { return body; }
}

function businessError(body) {
  body = parseBody(body);
  if (body == null) return '';
  if (typeof body !== 'object') return '';
  if (body.error) {
    return typeof body.error === 'string' ? body.error : JSON.stringify(body.error);
  }
  if (body.status && String(body.status).toLowerCase() === 'error') {
    return JSON.stringify(body).slice(0, 1000);
  }
  return '';
}

function isRetryableQuickLinkBusinessError(body, bizError) {
  const parsed = parseBody(body);
  const errorCode = String(parsed?.error?.code || '').toLowerCase();
  const errorText = String(bizError || parsed?.error?.message || '').toLowerCase();
  return errorCode === 'resourcemodified'
    || (errorText.includes('resourcemodified') && errorText.includes('etag'))
    || errorText.includes('etag mismatch');
}

return httpItems.map((item, index) => {
  const report = reports[index] || {};
  const http = item.json || {};
  const statusCode = Number(http.statusCode || http.status || http.code || 0);
  const body = http.body ?? http.data ?? http;
  const bizError = businessError(body);
  const ok = statusCode >= 200 && statusCode < 300 && !bizError;
  const response = {
    statusCode: statusCode || null,
    headers: http.headers || null,
    body,
  };

  const responseJson = esc(JSON.stringify(response).slice(0, 20000));
  const queueId = esc(report.queue_id);
  let dbQuery;
  let errorMsg = null;
  const retry = isRetryableQuickLinkBusinessError(body, bizError)
    || (!bizError && (statusCode >= 500 || statusCode === 0));
  if (ok) {
    dbQuery = `SELECT * FROM complete_quicklink_report_success('${queueId}'::uuid, '${responseJson}'::jsonb);`;
  } else {
    errorMsg = esc(`HTTP ${statusCode || 'unknown'} ${bizError ? 'business_error ' + bizError : JSON.stringify(body).slice(0, 700)}`);
    dbQuery = `SELECT * FROM fail_quicklink_report('${queueId}'::uuid, '${errorMsg}'::text, '${responseJson}'::jsonb, ${retry ? 'true' : 'false'});`;
  }

  return { json: {
    ...report,
    http_status_code: statusCode || null,
    post_ok: ok,
    retry,
    db_query: dbQuery,
    error_msg: errorMsg,
    quicklink_response: response,
  } };
});

const dbItems = $input.all();
let completions = [];
try {
  completions = $('Code - Build Completion Query').all().map(item => item.json || {});
} catch (e) {
  completions = [];
}

const results = dbItems.map((item, index) => {
  const src = completions[index] || {};
  const db = item.json || {};
  return {
    status: src.post_ok ? 'real_post_sent' : 'real_post_failed',
    dry_run: false,
    real_post_requested: true,
    source: src.source || 'schedule',
    worker_id: src.worker_id,
    queue_id: src.queue_id,
    conversation_id: src.conversation_id,
    lead_id: src.lead_id,
    quicklink_id: src.quicklink_id,
    marca: src.marca,
    endpoint: src.endpoint,
    http_status_code: src.http_status_code,
    queue_status: src.post_ok ? 'SENT' : (src.retry ? 'PENDING' : 'FAILED'),
    db_result: db,
  };
});

const sentCount = results.filter(r => r.status === 'real_post_sent').length;
const failedCount = results.length - sentCount;

return [{ json: {
  status: failedCount ? 'real_post_partial_or_failed' : 'real_post_batch_sent',
  dry_run: false,
  real_post_requested: true,
  report_count: results.length,
  sent_count: sentCount,
  failed_count: failedCount,
  results,
} }];
